const fail = (ms, message) =>
  new Promise((resolve, reject) => setTimeout(() => reject(new Error(message)), ms));

async function a() {
  try {
    return fail(10, "a");
  } catch {
    return "a caught";
  } finally {
    console.log("a finally");
  }
}

async function b() {
  try {
    return await fail(30, "b");
  } catch {
    return "b caught";
  } finally {
    console.log("b finally");
  }
}

a().then(
  (value) => console.log(value),
  () => console.log("a rejected")
);
b().then((value) => console.log(value));
